#!/usr/bin/env python3
# Generated by Claudian.
"""Pre-generate the phrases Jarvis says most, so they never cost a network call.

    python3 warm_voice_cache.py           # generate
    python3 warm_voice_cache.py --status  # show cache contents
    python3 warm_voice_cache.py --clear   # wipe it

Jarvis repeats itself constantly: greetings, acknowledgements, "opening
Chrome", error messages. Every one of those is a round trip to ElevenLabs the
first time. Cached, they replay from disk with no network involved at all —
the only genuinely zero-latency speech the neural voice can produce.

Costs a few hundred characters of quota, once.
"""

from __future__ import annotations

import argparse
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).parent))

# Phrases worth caching: short, frequent, and word-for-word identical every
# time. Anything with a variable in it would never hit the cache.
COMMON_PHRASES = [
    # Greetings / sign-offs
    "Good morning.", "Good afternoon.", "Good evening.",
    "Hello.", "Hi there.", "I'm here.", "At your service.",
    "Goodbye.", "Talk soon.", "Shutting down.", "Going quiet.",

    # Acknowledgements
    "Sure thing.", "Done.", "On it.", "Got it.", "Of course.",
    "Right away.", "Consider it done.", "No problem.", "Okay.",
    "Yes?", "Go ahead.", "I'm listening.",

    # Common actions
    "Opening it now.", "Closing that.", "Playing now.", "Paused.",
    "Skipping.", "Muted.", "Unmuted.", "Volume set.",
    "Brightness set.", "Screenshot saved to your desktop.",
    "Screen locked.", "Trash emptied.", "Searching.",
    "Let me look that up.", "One moment.", "Working on it.",

    # Failure modes
    "Something went wrong. Please try again.",
    "I couldn't find that.",
    "I didn't catch that.",
    "Sorry, could you say that again?",
    "I can't reach the network right now.",
    "That app doesn't seem to be installed.",
    "I'm not sure how to help with that.",
]


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--status", action="store_true")
    ap.add_argument("--clear", action="store_true")
    args = ap.parse_args()

    from voice.speech_engines import CACHE_DIR, ElevenLabsEngine
    from config import settings

    if args.clear:
        n = 0
        for f in CACHE_DIR.glob("*.pcm"):
            f.unlink()
            n += 1
        print(f"Cleared {n} cached phrase(s).")
        return 0

    if args.status:
        files = list(CACHE_DIR.glob("*.pcm"))
        total = sum(f.stat().st_size for f in files)
        print(f"Cached phrases : {len(files)}")
        print(f"Disk used      : {total / 1024 / 1024:.1f} MB")
        print(f"Location       : {CACHE_DIR}")
        # PCM at 22050Hz, 16-bit mono = 44100 bytes per second
        if total:
            print(f"Audio cached   : {total / 44100:.0f}s of speech")
        return 0

    if settings.TTS_ENGINE != "elevenlabs":
        print("TTS_ENGINE is not 'elevenlabs' — nothing to warm.")
        print("Set TTS_ENGINE=elevenlabs in .env first.")
        return 1

    if not settings.ELEVENLABS_API_KEY:
        print("ELEVENLABS_API_KEY is not set in .env.")
        print("Get one at https://elevenlabs.io/app/settings/api-keys")
        return 1

    engine = ElevenLabsEngine(
        api_key=settings.ELEVENLABS_API_KEY,
        voice_id=settings.ELEVENLABS_VOICE_ID,
        model=settings.ELEVENLABS_MODEL,
    )
    if not engine.available():
        print("ElevenLabs engine unavailable — check pyaudio and requests.")
        return 1

    existing = len(list(CACHE_DIR.glob("*.pcm")))
    todo = sum(1 for p in COMMON_PHRASES if not engine._cache_path(p).exists())

    print(f"Phrases         : {len(COMMON_PHRASES)}")
    print(f"Already cached  : {len(COMMON_PHRASES) - todo}")
    print(f"To generate     : {todo}")
    chars = sum(len(p) for p in COMMON_PHRASES if not engine._cache_path(p).exists())
    print(f"Quota cost      : ~{chars} characters (one time)")
    print()

    if todo == 0:
        print("Nothing to do — cache is warm.")
        return 0

    print("Generating...")
    made = engine.warm_cache(COMMON_PHRASES)
    print()
    print(f"Generated {made} phrase(s). Cache now holds "
          f"{len(list(CACHE_DIR.glob('*.pcm')))} (was {existing}).")
    print("Those now play with zero network latency.")
    return 0


if __name__ == "__main__":
    sys.exit(main())
